/* port/data/pc_data.c: fill the game's data from the ROM (docs/port/DATA.md).
 *
 * The tables (pc_data.h; the game's are generated by tools/port/gen_data.py) say, per image, where its bytes are
 * in the ROM, which N64 range is its data and BSS, and how every known symbol is laid out. Loading an image:
 *
 *   1. its bytes: a slice of the ROM, or a raw DEFLATE stream inflated once and kept for overlay reloads;
 *   2. each arena (the image's data and BSS in N64 layout): copy the initialized part, zero the BSS, and
 *      byte-swap the elements the runs describe in place (pointers stay N64 addresses there);
 *   3. each symbol with its own storage: convert from the image through its runs, turning N64 pointers into host
 *      pointers (functions, own storage, game-C data, arenas). Addresses in the game heap (at or above the tables'
 *      heap_lo, outside the runtime images) stay as they are: the heap is the RDRAM window at host 0x80000000
 *      (pc_port.h), so they are valid host addresses, and the renderer reads values below 4 GB as N64 addresses;
 *   4. game-C data in an overlay: put back the bytes it had at startup (or zero it), the symbols the tables name and
 *      the image's C ranges, which hold the statics no table can name.
 *
 * The game's arenas are at their N64 addresses in that window too, so an N64 address inside one is its own host
 * address (arena + offset is the identity), and 32-bit fields can hold it. The window must be mapped first. The
 * test tables may keep their arenas in host memory instead.
 *
 * The first load writes a report: pointer counts, unresolved pointers, and non-pointer words that look like N64
 * addresses (likely mistyped declarations, unless they point at window data). */
#include "pc_data.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#ifdef _WIN32
#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#else
#include <sys/mman.h>
#include <unistd.h>
#endif
#include <zlib.h>

#ifndef PC_DATA_REPORT_DEFAULT
#define PC_DATA_REPORT_DEFAULT ""
#endif

static PcDataStats g_stats;
static FILE *g_report;
static int g_scan;              /* first load: count and report */

/* Values already logged as unresolved (once each). */
#define LOGGED_SLOTS 4096
static uint32_t g_logged[LOGGED_SLOTS];

static int log_once(uint32_t v)
{
    uint32_t h = (v * 2654435761u) & (LOGGED_SLOTS - 1);
    for (int i = 0; i < LOGGED_SLOTS; i++, h = (h + 1) & (LOGGED_SLOTS - 1)) {
        if (g_logged[h] == v)
            return 0;
        if (g_logged[h] == 0) {
            g_logged[h] = v;
            return 1;
        }
    }
    return 0;
}

static uint16_t rd16(const uint8_t *p) { return (uint16_t)(p[0] << 8 | p[1]); }
static uint32_t rd32(const uint8_t *p) { return (uint32_t)p[0] << 24 | (uint32_t)p[1] << 16 | (uint32_t)p[2] << 8 | p[3]; }
static uint64_t rd64(const uint8_t *p) { return (uint64_t)rd32(p) << 32 | rd32(p + 4); }

static uint32_t n64_esz(int kind)
{
    static const uint8_t sz[PC_K_COUNT] = {0, 1, 2, 4, 4, 8, 8, 4, 4, 4};
    return kind > 0 && kind < PC_K_COUNT ? sz[kind] : 0;
}

static uint32_t host_esz(int kind)
{
    if (kind == PC_K_PTR)
        return sizeof(void *);
    if (kind == PC_K_S32_64 || kind == PC_K_U32_64)
        return 8;
    return n64_esz(kind);
}

/* ---------------------------------------------------------------- lookups */

static const PcDataSym *find_sym(const PcDataTables *t, uint32_t a)
{
    uint32_t lo = 0, hi = t->n_syms;
    while (lo < hi) {   /* first symbol above a */
        uint32_t mid = (lo + hi) / 2;
        if (t->syms[mid].n64_addr <= a)
            lo = mid + 1;
        else
            hi = mid;
    }
    if (lo == 0)
        return NULL;
    const PcDataSym *s = &t->syms[lo - 1];
    return a < s->n64_addr + (s->n64_size ? s->n64_size : 1) ? s : NULL;
}

static const PcDataFunc *find_func(const PcDataTables *t, uint32_t a, int image)
{
    uint32_t lo = 0, hi = t->n_funcs;
    while (lo < hi) {
        uint32_t mid = (lo + hi) / 2;
        if (t->funcs[mid].n64_addr < a)
            lo = mid + 1;
        else
            hi = mid;
    }
    const PcDataFunc *any = NULL;
    for (; lo < t->n_funcs && t->funcs[lo].n64_addr == a; lo++) {
        if (image < 0 || t->funcs[lo].image == image)
            return &t->funcs[lo];
        if (!any)
            any = &t->funcs[lo];
    }
    return image < 0 ? any : NULL;
}

static const PcDataName *find_name(const PcDataTables *t, uint32_t a)
{
    uint32_t lo = 0, hi = t->n_names;
    while (lo < hi) {
        uint32_t mid = (lo + hi) / 2;
        if (t->names[mid].n64_addr <= a)
            lo = mid + 1;
        else
            hi = mid;
    }
    return lo ? &t->names[lo - 1] : NULL;
}

static int is_overlay(const PcDataTables *t, int image)
{
    return image >= 0 && (uint32_t)image < t->n_images && t->images[image].n64_base >= 0x80300000u;
}

/* Host offset of N64 offset off inside symbol s, through its runs. *exact is 0 for padding. */
static uint32_t map_offset(const PcDataTables *t, const PcDataSym *s, uint32_t off, int *exact)
{
    uint32_t best_n = 0, best_h = 0;
    *exact = 1;
    if (!s->run_count)
        return off;
    for (uint32_t k = 0; k < s->run_count; k++) {
        const PcDataRun *r = &t->runs[s->run_first + k];
        if (off < r->n64_off)
            continue;
        uint32_t en = n64_esz(r->kind), eh = host_esz(r->kind);
        uint32_t i = r->n64_stride ? (off - r->n64_off) / r->n64_stride : 0;
        if (i >= r->rep)
            i = r->rep - 1;
        uint32_t within = off - r->n64_off - i * r->n64_stride;
        uint32_t j = within / en;
        if (j < r->count) {
            uint32_t sub = within - j * en;
            return r->host_off + i * r->host_stride + j * eh + (sub < eh ? sub : eh - 1);
        }
        uint32_t end_n = r->n64_off + i * r->n64_stride + r->count * en;
        if (end_n <= off && end_n >= best_n) {
            best_n = end_n;
            best_h = r->host_off + i * r->host_stride + r->count * eh;
        }
    }
    *exact = 0;
    return best_h + (off - best_n);
}

/* Describe an N64 address by name, for the report. */
static void describe(const PcDataTables *t, uint32_t a, char *buf, size_t n)
{
    const PcDataFunc *f = find_func(t, a, -1);
    const PcDataSym *s;
    const PcDataName *nm;
    if (f)
        snprintf(buf, n, "%s()%s", f->name, f->host ? "" : " [no C]");
    else if ((s = find_sym(t, a)) != NULL)
        snprintf(buf, n, "%s+0x%X", s->name, a - s->n64_addr);
    else if ((nm = find_name(t, a)) != NULL && a - nm->n64_addr < 0x10000)
        snprintf(buf, n, "%s+0x%X", nm->name, a - nm->n64_addr);
    else
        snprintf(buf, n, "?");
}

static int at_n64_address(const PcDataArena *ar)
{
    return (uintptr_t)ar->host == ar->n64_lo;
}

/* What an address-like word points at, for the report. Data in the window (an arena at its N64 address, outside
 * own storage and game-C data; the heap; low memory) is reachable through the 32-bit value as it is: *host = 0.
 * Own storage, game-C data and functions are host memory, and code is not data: a u32 can't reach them. */
static const char *addr_class(const PcDataTables *t, uint32_t v, int *host)
{
    const PcDataSym *s = find_sym(t, v);
    *host = 1;
    if (find_func(t, v, -1))
        return "function";
    if (s && s->host)
        return s->flags & PC_SYM_OWN ? "own" : "C data";
    for (uint32_t i = 0; i < t->n_arenas; i++)
        if (v >= t->arenas[i].n64_lo && v < t->arenas[i].n64_hi) {
            *host = !at_n64_address(&t->arenas[i]);
            return "arena";
        }
    for (uint32_t i = 0; i < t->n_images; i++)
        if (v >= t->images[i].n64_base && v - t->images[i].n64_base < t->images[i].size)
            return "code";   /* an image's bytes outside its arena */
    if (v >= t->heap_lo || v < 0x80000400u) {
        *host = 0;
        return v >= t->heap_lo ? "heap" : "low memory";
    }
    return "code";
}

static void report_addr_word(const PcDataTables *t, const char *where, uint32_t v)
{
    int host;
    const char *cls = addr_class(t, v, &host);
    g_stats.addr_words++;
    g_stats.addr_words_host += host;
    if (g_report) {
        char target[96];
        describe(t, v, target, sizeof target);
        fprintf(g_report, "addr-word %s 0x%08X -> %s [%s]\n", where, v, target, cls);
    }
}

/* The kind of the element runs[first..first+count) describe at N64 offset o (and so swap), or 0. */
static int run_kind(const PcDataTables *t, uint32_t first, uint32_t count, uint32_t o)
{
    for (uint32_t k = 0; k < count; k++) {
        const PcDataRun *r = &t->runs[first + k];
        uint32_t len = r->count * n64_esz(r->kind);
        if (o < r->n64_off)
            continue;
        if (r->rep <= 1 || r->n64_stride == 0) {
            if (o - r->n64_off < len)
                return r->kind;
        } else if ((o - r->n64_off) / r->n64_stride < r->rep && (o - r->n64_off) % r->n64_stride < len) {
            return r->kind;
        }
    }
    return 0;
}

/* ... at N64 address a of an arena's initialized data. */
static int arena_kind(const PcDataTables *t, const PcDataArena *ar, uint32_t a)
{
    return run_kind(t, ar->run_first, ar->run_count, a - ar->n64_lo);
}

static void report_text(const PcDataTables *t, const char *where, uint32_t off, uint32_t v, uint32_t a,
                        const char *text)
{
    g_stats.text_in_words++;
    if (g_report) {
        char target[96];
        describe(t, a, target, sizeof target);
        fprintf(g_report, "text-in-words %s+0x%X 0x%08X -> %s (%.16s)\n", where, off, v, target, text);
    }
}

/* Whether the image's bytes at N64 address a read as text: three printable characters or more, then a NUL. A
 * pointer to text inside an element wider than a byte means a declaration that runs over a string (a table sized by
 * the gap to the next known address, say): the loader swaps the text with the words. NULL if not. */
static const char *image_text(const PcDataTables *t, int image, uint32_t a)
{
    const PcDataImage *im = &t->images[image];
    const uint8_t *img = t->state ? t->state->image[image] : NULL;
    uint32_t o = a - im->n64_base, n = 0;
    if (!img || a < im->n64_base || o >= im->size)
        return NULL;
    while (o + n < im->size && n < 64 && img[o + n] >= 0x20 && img[o + n] < 0x7F)
        n++;
    return n >= 3 && o + n < im->size && img[o + n] == 0 ? (const char *)img + o : NULL;
}

/* N64 pointer value v, found in image `image`'s data at where+off -> host pointer. */
static void *resolve(const PcDataTables *t, uint32_t v, int image, const char *where, uint32_t off, int quiet)
{
    uint32_t a = v;
    int ovl_ctx = is_overlay(t, image);
    if (v == 0) {
        if (!quiet) g_stats.null++;
        return NULL;
    }
    if (a >= 0xA0000000u && a < 0xC0000000u)
        a -= 0x20000000u;   /* KSEG1 -> KSEG0 */
    if (a < 0x80000000u || a >= 0x80800000u) {
        if (!quiet) g_stats.raw++;   /* not an RDRAM address: a ROM offset or segment address, kept as is */
        if (v >= 0xFFFFF000u)        /* a small negative sentinel such as (char *)-1: sign-extended, so the */
            return (void *)(intptr_t)(int32_t)v;   /* game's comparisons with (T *)-1 still match */
        return (void *)(uintptr_t)v;
    }
    /* In a runtime image (its code, data or BSS)? Those live in host code and arenas, not in the window. */
    int in_ovl = 0;
    for (uint32_t i = 0; i < t->n_images && !in_ovl; i++)
        in_ovl = is_overlay(t, (int)i) && a >= t->images[i].n64_base && a < t->images[i].n64_base + t->images[i].size;
    for (uint32_t i = 0; i < t->n_arenas && !in_ovl; i++)
        in_ovl = is_overlay(t, t->arenas[i].image) && a >= t->arenas[i].n64_lo && a <= t->arenas[i].n64_hi;
    if (a >= t->heap_lo && !in_ovl) {
        if (!quiet) g_stats.rdram++;   /* the game heap, frame buffers: kept */
        return (void *)(uintptr_t)v;
    }
    /* 1. A function: this image's (the runtime images share code addresses), or any image's from game data. */
    const PcDataFunc *f = find_func(t, a, ovl_ctx ? image : -1);
    if (f && f->host) {
        if (!quiet) {
            g_stats.func++;
            if (!ovl_ctx && ((f > t->funcs && f[-1].n64_addr == a)
                             || (f + 1 < t->funcs + t->n_funcs && f[1].n64_addr == a)))
                g_stats.ambiguous++;   /* both runtime images have a function here; the first is used */
        }
        return f->host;
    }
    /* 2. Data: own storage or game-C data, then the arenas. In the overlay range, only this image's. */
    const PcDataSym *s = find_sym(t, a);
    if (s && s->host && (!in_ovl || !ovl_ctx || s->image == image)) {
        int exact;
        uint32_t ho = map_offset(t, s, a - s->n64_addr, &exact);
        if (!quiet) {
            if (s->flags & PC_SYM_OWN) g_stats.own++; else g_stats.cdef++;
            if (!exact) g_stats.inexact++;
            const char *text = !(s->flags & PC_SYM_BSS) && run_kind(t, s->run_first, s->run_count,
                                                                     a - s->n64_addr) > PC_K_U8
                               ? image_text(t, s->image, a) : NULL;
            if (text)
                report_text(t, where, off, v, a, text);   /* own storage converts it as wider elements too */
        }
        return (uint8_t *)s->host + ho;
    }
    for (uint32_t i = 0; i < t->n_arenas; i++) {
        const PcDataArena *ar = &t->arenas[i];
        if (a >= ar->n64_lo && a <= ar->n64_hi && (!in_ovl || !ovl_ctx || ar->image == image)) {
            if (!quiet) {
                g_stats.arena++;
                int kind = a < ar->n64_init ? arena_kind(t, ar, a) : -1;
                const char *text = kind > PC_K_U8 || kind == 0 ? image_text(t, ar->image, a) : NULL;
                if (kind == 0) {
                    g_stats.undescribed++;
                    if (g_report) {   /* text there is fine as it is; a table of wider values is not */
                        char target[96];
                        describe(t, a, target, sizeof target);
                        fprintf(g_report, "undescribed %s+0x%X 0x%08X -> %s%s\n", where, off, v, target,
                                text ? " (text)" : "");
                    }
                } else if (text) {
                    report_text(t, where, off, v, a, text);
                }
            }
            return ar->host + (a - ar->n64_lo);
        }
    }
    /* 3. A function with no C yet, or another runtime image's function. */
    if (!f)
        f = find_func(t, a, -1);
    if (f) {
        if (f->host) {
            if (!quiet) g_stats.func++;
            return f->host;
        }
        if (!quiet) {
            g_stats.no_code++;
            if (log_once(v)) {
                fprintf(stderr, "pc_data: %s+0x%X points to %s (0x%08X), which has no C yet\n", where, off,
                        f->name, v);
                if (g_report)
                    fprintf(g_report, "no-code %s+0x%X 0x%08X %s\n", where, off, v, f->name);
            }
        }
        return NULL;
    }
    if (a >= t->heap_lo) {
        if (!quiet) g_stats.rdram++;   /* inside the heap block reserved for the runtime images */
        return (void *)(uintptr_t)v;
    }
    if (!quiet) {
        g_stats.unresolved++;
        if (log_once(v)) {
            fprintf(stderr, "pc_data: unresolved pointer 0x%08X in %s+0x%X\n", v, where, off);
            if (g_report)
                fprintf(g_report, "unresolved %s+0x%X 0x%08X\n", where, off, v);
        }
    }
    return (void *)(uintptr_t)v;
}

void *pc_data_host_of(const PcDataTables *t, uint32_t n64_addr, int image)
{
    return resolve(t, n64_addr, image, "?", 0, 1);
}

/* ---------------------------------------------------------------- images */

static int inflate_raw(const uint8_t *src, size_t len, uint8_t *dst, size_t size)
{
    z_stream z;
    memset(&z, 0, sizeof z);
    if (inflateInit2(&z, -15) != Z_OK)
        return -1;
    z.next_in = (Bytef *)src;
    z.avail_in = (uInt)len;
    z.next_out = dst;
    z.avail_out = (uInt)size;
    int r = inflate(&z, Z_FINISH);
    size_t out = size - z.avail_out;
    inflateEnd(&z);
    return r == Z_STREAM_END && out == size ? 0 : -1;
}

static uint8_t *image_bytes(const PcDataTables *t, int i)
{
    PcDataState *st = t->state;
    const PcDataImage *im = &t->images[i];
    if (st->image[i])
        return st->image[i];
    if (!st->rom || (size_t)im->rom_off + im->rom_len > st->rom_size) {
        fprintf(stderr, "pc_data: image %s is outside the ROM\n", im->name);
        return NULL;
    }
    if (im->storage == PC_IMG_RAW) {
        if (im->rom_len < im->size)
            return NULL;
        st->image[i] = (uint8_t *)st->rom + im->rom_off;
        return st->image[i];
    }
    uint8_t *buf = malloc(im->size);
    if (!buf || inflate_raw(st->rom + im->rom_off, im->rom_len, buf, im->size) != 0) {
        fprintf(stderr, "pc_data: the stream at ROM 0x%X does not inflate to image %s (%u B)\n", im->rom_off,
                im->name, im->size);
        free(buf);
        return NULL;
    }
    st->image[i] = st->owned[i] = buf;
    return buf;
}

/* ---------------------------------------------------------------- filling */

static void swap_arena(const PcDataTables *t, const PcDataArena *ar)
{
    for (uint32_t k = 0; k < ar->run_count; k++) {
        const PcDataRun *r = &t->runs[ar->run_first + k];
        uint32_t en = n64_esz(r->kind);
        for (uint32_t i = 0; i < r->rep; i++) {
            uint8_t *p = ar->host + r->n64_off + i * r->n64_stride;
            for (uint32_t j = 0; j < r->count; j++, p += en) {
                if (p + en > ar->host + (ar->n64_init - ar->n64_lo))
                    break;
                if (en == 2) {
                    uint16_t v = rd16(p);
                    memcpy(p, &v, 2);
                } else if (en == 4) {
                    uint32_t v = rd32(p);
                    memcpy(p, &v, 4);
                    if (g_scan && r->kind == PC_K_U32 && v >= 0x80000000u && v < 0x80800000u) {
                        char what[96];
                        describe(t, ar->n64_lo + (uint32_t)(p - ar->host), what, sizeof what);
                        report_addr_word(t, what, v);
                    }
                } else if (en == 8) {
                    uint64_t v = rd64(p);
                    memcpy(p, &v, 8);
                }
            }
        }
    }
}

/* The N64 bytes src (n64_size of them, `avail` in the image) to host bytes dst (host_size) through the runs
 * runs[first..first+count): byte order per element, N64 pointers to host pointers. */
static void convert_runs(const PcDataTables *t, uint32_t first, uint32_t count, const uint8_t *src, uint32_t n64_size,
                         uint32_t avail, uint8_t *dst, uint32_t host_size, int image, const char *where)
{
    memset(dst, 0, host_size);
    for (uint32_t k = 0; k < count; k++) {
        const PcDataRun *r = &t->runs[first + k];
        uint32_t en = n64_esz(r->kind), eh = host_esz(r->kind);
        for (uint32_t i = 0; i < r->rep; i++) {
            for (uint32_t j = 0; j < r->count; j++) {
                uint32_t no = r->n64_off + i * r->n64_stride + j * en;
                uint32_t ho = r->host_off + i * r->host_stride + j * eh;
                if (no + en > n64_size || no + en > avail || ho + eh > host_size)
                    continue;
                const uint8_t *p = src + no;
                uint8_t *q = dst + ho;
                switch (r->kind) {
                case PC_K_U8: *q = *p; break;
                case PC_K_U16: { uint16_t v = rd16(p); memcpy(q, &v, 2); break; }
                case PC_K_U32:
                case PC_K_F32: { uint32_t v = rd32(p); memcpy(q, &v, 4); break; }
                case PC_K_U64:
                case PC_K_F64: { uint64_t v = rd64(p); memcpy(q, &v, 8); break; }
                case PC_K_S32_64: { int64_t v = (int32_t)rd32(p); memcpy(q, &v, 8); break; }
                case PC_K_U32_64: { uint64_t v = rd32(p); memcpy(q, &v, 8); break; }
                case PC_K_PTR: {
                    void *h = resolve(t, rd32(p), image, where, no, !g_scan);
                    memcpy(q, &h, sizeof h);
                    break;
                }
                }
            }
        }
    }
}

static void convert_sym(const PcDataTables *t, const PcDataSym *s, const uint8_t *img, uint32_t img_size, int image)
{
    uint32_t base = s->n64_addr - t->images[image].n64_base;
    if (base > img_size) {
        memset(s->host, 0, s->host_size);
        return;
    }
    convert_runs(t, s->run_first, s->run_count, img + base, s->n64_size, img_size - base, s->host, s->host_size, image,
                 s->name);
}

/* ---------------------------------------------------------------- tables only pointers reach */

/* What a rule made on an image's load: host storage for a converted table, or the mark of one swapped in place. */
typedef struct ReachBlock {
    struct ReachBlock *next;
    int32_t rule;
    uint32_t n64;
    uint8_t *host;   /* NULL: swapped in place */
} ReachBlock;

/* The loaded image bytes at N64 address a, n of them, from image `image` first (the runtime images share
 * addresses); *avail: how many there are to the image's end. */
static const uint8_t *image_at(const PcDataTables *t, int image, uint32_t a, uint32_t n, uint32_t *avail)
{
    for (int pass = 0; pass < 2; pass++)
        for (uint32_t i = 0; i < t->n_images; i++) {
            const PcDataImage *im = &t->images[i];
            const uint8_t *b = t->state ? t->state->image[i] : NULL;
            if ((pass == 0) != ((int)i == image) || !b || a < im->n64_base || (uint64_t)a - im->n64_base + n > im->size)
                continue;
            *avail = im->size - (a - im->n64_base);
            return b + (a - im->n64_base);
        }
    return NULL;
}

static uint32_t rd_width(const uint8_t *p, uint32_t w)
{
    return w == 1 ? *p : w == 2 ? rd16(p) : rd32(p);
}

/* How many elements rule r reaches at b (avail bytes to the image's end): 0 when the table has no end there. */
static uint32_t reach_count(const PcDataTables *t, const PcDataReach *r, const uint8_t *b, uint32_t avail,
                            const uint8_t *parent, uint32_t slot, int image)
{
    uint32_t n = r->count, a;
    if (r->count_kind == PC_REACH_UNTIL) {
        for (n = 1; n <= 4096 && (uint64_t)n * r->n64_size <= avail; n++)
            if (rd_width(b + (n - 1) * r->n64_size + r->field_n64, r->field_width) == 0)
                return n;
        return 0;
    }
    if (r->count_kind == PC_REACH_PARENT)
        n = parent ? rd_width(parent + r->field_n64, r->field_width) : 0;
    else if (r->count_kind == PC_REACH_TABLE) {
        const uint8_t *tb = image_at(t, image, r->table_n64 + slot * r->field_width, r->field_width, &a);
        n = tb ? rd_width(tb, r->field_width) : 0;
    }
    return n <= 4096 && (uint64_t)n * r->n64_size <= avail ? n : 0;
}

/* The element bytes in an arena at N64 address a swapped in place through the runs, unless an element describes
 * them already: 1 if they were. */
static int swap_in_place(const PcDataTables *t, const PcDataReach *r, uint32_t a, uint32_t n)
{
    for (uint32_t i = 0; i < t->n_arenas; i++) {
        const PcDataArena *ar = &t->arenas[i];
        if (a < ar->n64_lo || (uint64_t)a + (uint64_t)n * r->n64_size > ar->n64_init || arena_kind(t, ar, a))
            continue;
        for (uint32_t e = 0; e < n; e++)
            for (uint32_t k = 0; k < r->run_count; k++) {
                const PcDataRun *run = &t->runs[r->run_first + k];
                uint32_t en = n64_esz(run->kind);
                for (uint32_t x = 0; x < run->rep; x++)
                    for (uint32_t j = 0; j < run->count; j++) {
                        uint32_t no = run->n64_off + x * run->n64_stride + j * en;
                        uint8_t *p = ar->host + (a - ar->n64_lo) + e * r->n64_size + no;
                        if (no + en > r->n64_size)
                            continue;
                        if (en == 2) {
                            uint16_t v = rd16(p);
                            memcpy(p, &v, 2);
                        } else if (en == 4) {
                            uint32_t v = rd32(p);
                            memcpy(p, &v, 4);
                        } else if (en == 8) {
                            uint64_t v = rd64(p);
                            memcpy(p, &v, 8);
                        }
                    }
            }
        return 1;
    }
    return 0;
}

/* The host pointer for the N64 pointer v that rule ri reaches: storage made for the table it points to (once per
 * load), or the table swapped in place and v resolved as usual. parent: the N64 bytes of the element holding v (a
 * field rule); slot: the index of v in a root rule's table. */
static void *reach_target(const PcDataTables *t, int32_t ri, uint32_t v, const uint8_t *parent, uint32_t slot,
                          int image)
{
    const PcDataReach *r = &t->reach[ri];
    PcDataState *st = t->state;
    uint32_t a = v >= 0xA0000000u && v < 0xC0000000u ? v - 0x20000000u : v, avail = 0;
    if (v == 0)
        return NULL;
    for (uint32_t i = 0; i < r->n_compatible; i++) {
        const PcDataSym *s = &t->syms[r->compatible[i]];
        if (a >= s->n64_addr && a < s->n64_addr + s->n64_size)
            return resolve(t, v, image, r->what, 0, 1);   /* storage that holds this type already */
    }
    for (ReachBlock *b = st->reached[image]; b; b = b->next)
        if (b->rule == ri && b->n64 == a)
            return b->host ? b->host : resolve(t, v, image, r->what, 0, 1);
    const uint8_t *src = image_at(t, image, a, r->n64_size, &avail);
    uint32_t n = src ? reach_count(t, r, src, avail, parent, slot, image) : 0;
    ReachBlock *blk = n ? calloc(1, sizeof *blk) : NULL;
    if (blk && r->copy && !(blk->host = calloc(n, r->host_size))) {
        free(blk);
        blk = NULL;
    }
    if (!blk) {
        if (g_report && g_scan && v >= 0x80000000u)
            fprintf(g_report, "reached %s 0x%08X: no table there\n", r->what, v);
        return resolve(t, v, image, r->what, 0, 1);
    }
    blk->rule = ri;
    blk->n64 = a;
    blk->next = st->reached[image];
    st->reached[image] = blk;
    int swapped = !r->copy && swap_in_place(t, r, a, n);
    if (g_scan) {
        g_stats.reached++;
        g_stats.reached_elems += n;
        if (g_report)
            fprintf(g_report, "reached %s 0x%08X: %u element%s, %s\n", r->what, v, n, n == 1 ? "" : "s",
                    r->copy ? "converted to storage of its own" : swapped ? "swapped in place"
                                                                          : "in place, described already");
    }
    if (!r->copy)
        return resolve(t, v, image, r->what, 0, 1);
    for (uint32_t e = 0; e < n; e++)
        convert_runs(t, r->run_first, r->run_count, src + e * r->n64_size, r->n64_size, avail - e * r->n64_size,
                     blk->host + e * r->host_size, r->host_size, image, r->what);
    for (uint32_t c = 0; c < t->n_reach; c++) {
        const PcDataReach *cr = &t->reach[c];
        if (cr->parent != ri)
            continue;
        for (uint32_t e = 0; e < n; e++) {
            const uint8_t *el = src + e * r->n64_size;
            void *h = reach_target(t, (int32_t)c, rd32(el + cr->slot_n64), el, e, image);
            memcpy(blk->host + e * r->host_size + cr->slot_host, &h, sizeof h);
        }
    }
    return blk->host;
}

/* The root rules of an image's symbols, after its load: what each of their pointers reaches. What the last load of
 * the image made goes first. */
static void reach_image(const PcDataTables *t, int image)
{
    PcDataState *st = t->state;
    uint32_t avail;
    for (ReachBlock *b = st->reached[image], *next; b; b = next) {
        next = b->next;
        free(b->host);
        free(b);
    }
    st->reached[image] = NULL;
    for (uint32_t ri = 0; ri < t->n_reach; ri++) {
        const PcDataReach *r = &t->reach[ri];
        const PcDataSym *s = r->sym >= 0 ? &t->syms[r->sym] : NULL;
        const uint8_t *b = s && s->image == image && s->host ? image_at(t, image, s->n64_addr, r->slots * 4, &avail)
                                                             : NULL;
        for (uint32_t i = 0; b && i < r->slots; i++) {
            int exact;
            void *h = reach_target(t, (int32_t)ri, rd32(b + 4 * i), NULL, i, image);
            memcpy((uint8_t *)s->host + map_offset(t, s, 4 * i, &exact), &h, sizeof h);
        }
    }
}

int pc_data_load_image(const PcDataTables *t, int image)
{
    if (image < 0 || (uint32_t)image >= t->n_images)
        return -1;
    const uint8_t *img = image_bytes(t, image);
    if (!img)
        return -1;
    uint32_t img_size = t->images[image].size, img_base = t->images[image].n64_base;
    for (uint32_t i = 0; i < t->n_arenas; i++) {
        const PcDataArena *ar = &t->arenas[i];
        if (ar->image != image)
            continue;
        uint32_t init = ar->n64_init - ar->n64_lo;
        if (ar->n64_lo < img_base || ar->n64_init - img_base > img_size)
            return -1;
        memcpy(ar->host, img + (ar->n64_lo - img_base), init);
        memset(ar->host + init, 0, ar->n64_hi - ar->n64_init);
        swap_arena(t, ar);
    }
    PcDataState *st = t->state;
    for (uint32_t i = 0; i < t->n_syms; i++) {
        const PcDataSym *s = &t->syms[i];
        if (s->image != image || !s->host)
            continue;
        if (s->flags & PC_SYM_OWN) {
            if (s->flags & PC_SYM_BSS)
                memset(s->host, 0, s->host_size);
            else
                convert_sym(t, s, img, img_size, image);
        } else if ((s->flags & PC_SYM_CDEF) && is_overlay(t, image) && st->loaded) {
            if (s->flags & PC_SYM_BSS)
                memset(s->host, 0, s->host_size);
            else if (st->snapshot && st->snapshot[i])
                memcpy(s->host, st->snapshot[i], s->host_size);
        }
    }
    for (uint32_t i = 0; is_overlay(t, image) && st->loaded && st->crange_snapshot && i < t->n_cranges; i++) {
        const PcDataCRange *r = &t->cranges[i];
        if (r->image == image && st->crange_snapshot[i])
            memcpy(r->start, st->crange_snapshot[i], (size_t)(r->end - r->start));
    }
    if (t->n_reach && image < 8)
        reach_image(t, image);
    return 0;
}

const PcDataStats *pc_data_stats(void)
{
    return &g_stats;
}

/* 1 if [p, p + n) is mapped. */
#ifdef _WIN32
static int mapped(const void *p, size_t n)
{
    MEMORY_BASIC_INFORMATION mi;
    for (const uint8_t *a = p, *end = a + n; a < end; a = (const uint8_t *)mi.BaseAddress + mi.RegionSize)
        if (!VirtualQuery(a, &mi, sizeof mi) || mi.State != MEM_COMMIT)
            return 0;
    return 1;
}
#else
static int mapped(const void *p, size_t n)
{
    uintptr_t page = (uintptr_t)sysconf(_SC_PAGESIZE), lo = (uintptr_t)p & ~(page - 1);
    return msync((void *)lo, (uintptr_t)p + n - lo, MS_ASYNC) == 0;
}
#endif

int pc_data_load_all(const PcDataTables *t, const uint8_t *rom, size_t rom_size, const char *report_path)
{
    PcDataState *st = t->state;
    const char *path = report_path;
    int rc = 0;
    /* An arena at its N64 address is in the RDRAM window, which must be mapped (port/ultra's pc_mem_init). */
    for (uint32_t i = 0; i < t->n_arenas; i++) {
        const PcDataArena *ar = &t->arenas[i];
        if (at_n64_address(ar) && !mapped(ar->host, ar->n64_hi - ar->n64_lo)) {
            fprintf(stderr, "pc_data: the game's data belongs at 0x%08X-0x%08X, in the RDRAM window at host "
                    "0x80000000, which is not mapped (docs/port/ULTRA.md)\n", ar->n64_lo, ar->n64_hi);
            return -1;
        }
    }
    st->rom = rom;
    st->rom_size = rom_size;
    if (!path)
        path = getenv("PC_DATA_REPORT");
    if (!path)
        path = PC_DATA_REPORT_DEFAULT;
    g_report = path[0] ? fopen(path, "w") : NULL;
    if (g_report)
        fprintf(g_report, "# pc_data report: unresolved pointers, pointers to functions with no C, and words in\n"
                          "# non-pointer fields that look like N64 addresses. Their target in brackets: [arena],\n"
                          "# [heap] and [low memory] are window data, which the word reaches as it is; [own],\n"
                          "# [C data], [function] and [code] it can't (likely mistyped declarations). An\n"
                          "# undescribed pointer's target is initialized data no declaration describes: its bytes\n"
                          "# keep the ROM's order, so a table of wider values there reads wrong. A text-in-words\n"
                          "# pointer's target reads as text but lies in an element wider than a byte, which swaps\n"
                          "# it: a declaration that runs over a string. A reached line is a table only pointers\n"
                          "# reach, which a rule of port/data/reached.txt converted\n");
    memset(&g_stats, 0, sizeof g_stats);
    memset(g_logged, 0, sizeof g_logged);
    /* Startup bytes of the game C's overlay data, put back on every overlay load. */
    if (!st->snapshot && t->n_syms)
        st->snapshot = calloc(t->n_syms, sizeof *st->snapshot);
    for (uint32_t i = 0; st->snapshot && i < t->n_syms; i++) {
        const PcDataSym *s = &t->syms[i];
        if ((s->flags & PC_SYM_CDEF) && !(s->flags & PC_SYM_BSS) && s->host && is_overlay(t, s->image)
            && !st->snapshot[i] && (st->snapshot[i] = malloc(s->host_size)) != NULL)
            memcpy(st->snapshot[i], s->host, s->host_size);
    }
    /* ... and of the runtime images' own C data, statics included. */
    if (!st->crange_snapshot && t->n_cranges)
        st->crange_snapshot = calloc(t->n_cranges, sizeof *st->crange_snapshot);
    for (uint32_t i = 0; st->crange_snapshot && i < t->n_cranges; i++) {
        const PcDataCRange *r = &t->cranges[i];
        size_t n = r->end > r->start ? (size_t)(r->end - r->start) : 0;
        if (n && !st->crange_snapshot[i] && (st->crange_snapshot[i] = malloc(n)) != NULL)
            memcpy(st->crange_snapshot[i], r->start, n);
    }
    /* Host storage must sit above 4 GB (a PIE build): the renderer reads values below it as N64 addresses. The
     * arenas at their N64 addresses are the exception, since there the N64 address is the host address. */
    if (sizeof(void *) == 8) {
        uintptr_t low = 0;
        for (uint32_t i = 0; i < t->n_arenas; i++)
            if (!at_n64_address(&t->arenas[i]) && (uintptr_t)t->arenas[i].host < ((uintptr_t)1 << 32))
                low = (uintptr_t)t->arenas[i].host;
        for (uint32_t i = 0; i < t->n_syms; i++)
            if (t->syms[i].host && (uintptr_t)t->syms[i].host < ((uintptr_t)1 << 32))
                low = (uintptr_t)t->syms[i].host;
        if (low) {
            fprintf(stderr, "pc_data: game data at host %p, below 4 GB: build the executable PIE\n", (void *)low);
            rc = -1;
        }
    }
    g_scan = 1;
    for (uint32_t i = 0; i < t->n_images; i++) {
        if (pc_data_load_image(t, (int)i) != 0) {
            fprintf(stderr, "pc_data: could not load image %s\n", t->images[i].name);
            rc = -1;
        }
    }
    g_scan = 0;
    st->loaded = 1;
    /* The game image is never loaded again. */
    for (uint32_t i = 0; i < t->n_images; i++) {
        if (!is_overlay(t, (int)i) && st->owned[i]) {
            free(st->owned[i]);
            st->owned[i] = st->image[i] = NULL;
        }
    }
    /* A runtime image's arena in the window lies in the game heap, which holds the image only once the game has
     * loaded it (PrevMaxPath reserves the block, then the load fills it again): until then it is heap memory, and
     * starts out zero like the rest of the heap. */
    for (uint32_t i = 0; i < t->n_arenas; i++) {
        const PcDataArena *ar = &t->arenas[i];
        if (is_overlay(t, ar->image) && at_n64_address(ar) && ar->n64_lo >= t->heap_lo)
            memset(ar->host, 0, ar->n64_hi - ar->n64_lo);
    }
    const PcDataStats *g = &g_stats;
    fprintf(stderr, "pc_data: %u symbols, pointers: %u own, %u C data, %u arena (%u to undescribed data, %u to text in "
            "words), %u functions, %u heap (kept), %u null, %u raw, %u unresolved, %u to functions with no C (%u "
            "inexact, %u ambiguous); %u address-like words (%u to host storage or code); %u tables only pointers "
            "reach (%u elements)\n",
            t->n_syms, g->own, g->cdef, g->arena, g->undescribed, g->text_in_words, g->func, g->rdram, g->null, g->raw,
            g->unresolved, g->no_code, g->inexact, g->ambiguous, g->addr_words, g->addr_words_host, g->reached,
            g->reached_elems);
    if (g_report) {
        fprintf(g_report, "# pointers: %u own, %u C data, %u arena (%u undescribed, %u text in words), %u functions, %u "
                "heap (kept), %u null, %u raw, %u unresolved, %u no C, %u inexact, %u ambiguous; %u address-like words "
                "(%u to host storage or code); %u tables only pointers reach (%u elements)\n", g->own, g->cdef, g->arena,
                g->undescribed, g->text_in_words, g->func, g->rdram, g->null, g->raw, g->unresolved, g->no_code,
                g->inexact, g->ambiguous, g->addr_words, g->addr_words_host, g->reached, g->reached_elems);
        fclose(g_report);
        g_report = NULL;
    }
    return rc;
}
